import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("Interval and duration must be positive")
    data = []
    start_time = time.time()
    while time.time() - start_time < duration:
        timestamp = time.time()
        if platform.system() == "Windows":
            cmd = ['wmic', 'cpu', 'get', 'loadpercentage']
            result = subprocess.run(cmd, capture_output=True, text=True)
            lines = result.stdout.strip().split('\n')
            if len(lines) > 1:
                usage = lines[1].strip()
                if usage.isdigit():
                    cpu_usage = float(usage)
                else:
                    cpu_usage = 0.0
            else:
                cpu_usage = 0.0
        else:
            cmd = ["top", "-bn1"]
            result = subprocess.run(cmd, capture_output=True, text=True)
            lines = result.stdout.split('\n')
            for line in lines:
                if "%Cpu(s)" in line:
                    parts = line.split(',')
                    idle = float(parts[3].split()[0].replace('id', ''))
                    cpu_usage = 100.0 - idle
                    break
            else:
                cpu_usage = 0.0
        data.append({"timestamp": timestamp, "cpu_usage": cpu_usage})
        time.sleep(interval)
    try:
        with open(LOGFILE_PATH, 'w') as f:
            json.dump(data, f)
        return LOGFILE_PATH
    except IOError:
        return None

